import unittest
from retry import should_retry

class RetryTests(unittest.TestCase):
    def test_transient_only(self):
        for value in (429, 500, 502, 503, 504):
            self.assertTrue(should_retry(value))
        for value in (200, 400, 401, 404, 501):
            self.assertFalse(should_retry(value))

