import unittest
from config import merge_flags

class ConfigTests(unittest.TestCase):
    def test_merge_without_mutation(self):
        defaults = {'safe': True, 'fast': False}
        self.assertEqual(merge_flags(defaults, {'fast': True}), {'safe': True, 'fast': True})
        self.assertEqual(defaults, {'safe': True, 'fast': False})

