import unittest
from finite_percent import parse_percent

class FinitePercentTests(unittest.TestCase):
    def test_valid(self):
        self.assertEqual(parse_percent(' 25.5 '), 25.5)
        self.assertEqual(parse_percent('0'), 0)
        self.assertEqual(parse_percent('100'), 100)
    def test_invalid(self):
        for value in ('-1', '101', 'abc'):
            with self.assertRaises(ValueError):
                parse_percent(value)

